// Service worker (generated by shared/pwa/make-pwa.mjs; edit sw-template.js, not the output).
// - Static files: cache-first from a versioned cache.
// - Navigations: network-first, falling back to the cached app shell.
// - /api/* and /ws/* never touch the cache.
// VERSION is a content hash of every precached file, so it changes whenever a file does.
const VERSION = '606ab090be';
const PREFIX = 'mafia-night-';
const CACHE = PREFIX + VERSION;

const SHELL = '/';
const PRECACHE = [
  '/',
  '/404.html',
  '/family.css',
  '/fonts/alegreya-sans-400.woff2',
  '/fonts/alegreya-sans-700.woff2',
  '/fonts/limelight-400.woff2',
  '/fonts/rubik-var.woff2',
  '/icons/apple-touch-icon.png',
  '/icons/favicon-32.png',
  '/icons/favicon.svg',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/icons/icon-maskable.svg',
  '/icons/icon.svg',
  '/icons/roles.svg',
  '/js/app.js',
  '/js/art.js',
  '/js/art_manifest.js',
  '/js/board.js',
  '/js/config-defaults.js',
  '/js/deck-key.js',
  '/js/engine.js',
  '/js/error-screen.js',
  '/js/faq.js',
  '/js/flair.js',
  '/js/footer.js',
  '/js/fx.js',
  '/js/graveyard.js',
  '/js/hold.js',
  '/js/host.js',
  '/js/host_help.js',
  '/js/host_help_core.js',
  '/js/host_v2.js',
  '/js/modes.js',
  '/js/motion.js',
  '/js/night-nav.js',
  '/js/player.js',
  '/js/preset-mixes.js',
  '/js/presets.js',
  '/js/print.js',
  '/js/qr.js',
  '/js/role_guide.js',
  '/js/role_icons.js',
  '/js/roles.js',
  '/js/roles_extra.js',
  '/js/roles_extra2.js',
  '/js/roles_sheet.js',
  '/js/role-types.js',
  '/js/room.js',
  '/js/setup-actions.js',
  '/js/seat-model.js',
  '/js/seating-actions.js',
  '/js/seating.js',
  '/js/setup-store.js',
  '/js/settle.js',
  '/js/setup-ui.js',
  '/js/simple.js',
  '/js/host-timeline.js',
  '/js/day-talk.js',
  '/js/state.js',
  '/js/theme.js',
  '/js/tools.js',
  '/js/ui_icons.js',
  '/js/wake.js',
  '/js/wordmark.js',
  '/js/world.js',
  '/manifest.webmanifest',
  '/print.css',
  '/print.html',
  '/pwa-install.js',
  '/redesign.css',
  '/setup.css',
  '/story.css',
  '/styles.css',
];

const isLive = (url) => url.pathname.startsWith('/api/') || url.pathname.startsWith('/ws/');
// A redirected response cannot answer a navigation, so only plain 200s are stored.
const storable = (res) => res && res.ok && res.status === 200 && !res.redirected && res.type === 'basic';

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // One file at a time, so a single missing file never blocks the install.
    await Promise.allSettled(PRECACHE.map(async (path) => {
      const res = await fetch(path, { cache: 'reload' });
      if (storable(res)) await cache.put(path, res);
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  const done = (async () => {
    const keys = await caches.keys();
    const stale = keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE);
    await Promise.all(stale.map((k) => caches.delete(k)));
    await self.clients.claim();
    return stale.length > 0;
  })();
  event.waitUntil(done);
  // On an update (an older cache existed), pages already open were drawn from the old cache and may be running old
  // HTML with no controllerchange listener, so reload them once. Not inside waitUntil: their navigation fetch waits
  // for activation to finish, so awaiting it there would deadlock.
  done.then(async (updated) => {
    if (!updated) return;
    const wins = await self.clients.matchAll({ type: 'window' });
    wins.forEach((c) => c.navigate(c.url).catch(() => {}));
  }).catch(() => {});
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || isLive(url)) return; // network only

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const res = await fetch(req, { cache: 'no-cache' }); // HTML always revalidated, never a stale HTTP-cache copy
        if (url.pathname === SHELL && storable(res)) {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(SHELL, copy));
        }
        return res;
      } catch {
        return (await caches.match(SHELL)) || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (storable(res)) {
      const copy = res.clone();
      caches.open(CACHE).then((c) => c.put(req, copy));
    }
    return res;
  })());
});
